/* Reports (files with a network link) generated by the agent across all
chats of a project, centralized on the project card — instead of scattered
links buried in n different chats. */

async function reportApi(path, options) {
  const resp = await fetch(path, options);
  if (!resp.ok) {
    const body = await resp.json().catch(() => ({}));
    throw new Error(body.detail || `${resp.status}`);
  }
  return resp.json();
}

function reportItem(projectId, report, onChange) {
  const li = document.createElement("li");
  li.className = "kb-file-item";

  const link = document.createElement("a");
  link.href = report.url;
  link.target = "_blank";
  link.rel = "noopener";
  link.textContent = report.filename;

  const meta = document.createElement("span");
  meta.className = "kb-file-status";
  meta.textContent = report.chat_title ? `from chat "${report.chat_title}"` : "chat deleted";

  if (report.raw_url && report.raw_url !== report.url) {
    const rawLink = document.createElement("a");
    rawLink.href = report.raw_url;
    rawLink.target = "_blank";
    rawLink.rel = "noopener";
    rawLink.className = "kb-file-raw-link";
    rawLink.title = "Open raw file";
    rawLink.textContent = "(raw)";
    meta.append(" ", rawLink);
  }

  const delBtn = document.createElement("button");
  delBtn.className = "kb-file-delete";
  delBtn.title = "Remove from list (the file on disk stays untouched)";
  delBtn.textContent = "✕";
  delBtn.addEventListener("click", async () => {
    await reportApi(`/api/projects/${projectId}/reports/${report.id}`, { method: "DELETE" });
    onChange();
  });

  li.append(link, meta, delBtn);
  return li;
}

function renderReports(projectId, list, onChange) {
  const box = document.createElement("div");
  box.className = "kb-box";

  const heading = document.createElement("div");
  heading.className = "project-field-label";
  heading.textContent = "Reports (files generated across this project's chats)";
  box.appendChild(heading);

  if (list.length === 0) {
    const empty = document.createElement("div");
    empty.className = "kb-empty";
    empty.textContent = "No reports yet.";
    box.appendChild(empty);
  } else {
    const ul = document.createElement("ul");
    ul.className = "kb-file-list";
    list.forEach((r) => ul.appendChild(reportItem(projectId, r, onChange)));
    box.appendChild(ul);
  }
  return box;
}

async function loadReportsInto(card, projectId) {
  let current = document.createElement("div");
  card.querySelector(".project-card-actions").before(current);
  const refresh = async () => {
    try {
      const list = await reportApi(`/api/projects/${projectId}/reports`);
      const box = renderReports(projectId, list, refresh);
      current.replaceWith(box);
      current = box;
    } catch (e) {
      const err = document.createElement("div");
      err.className = "kb-empty";
      err.textContent = `Reports could not be loaded: ${e.message}`;
      current.replaceWith(err);
      current = err;
    }
  };
  await refresh();
}
